-- V38__packloading_order_step_removal.sql
-- Page-by-page QA (2026-07-20) follow-up on M10.PackLoading:
--  1) Remove the duplicate in-flow "Loading Order Sheet" step. Order data lives
--     only in the M5 master (OrderDispatchDetail, loaded via OrderApp upload);
--     the flow now goes QC_PRELOAD_APPROVED -> LOADING_ALLOCATED directly.
--  2) Delete the weak unscoped page aria:loading-order-sheet.
--  3) Fix aria:pmt-unload-recheck: V37 left page_definition.current_version_id
--     pointing at the CAMERA page's version, so the backend served the wrong
--     body. Re-point it at the page's own PUBLISHED version (self-correcting,
--     so it is portable across environments with different version ids).
-- Idempotent + generic (applies to every tenant running M10.PackLoading).

-- 1) workflow: drop the ORDER_SHEET_UPLOADED step
UPDATE workflow_definition
   SET body_json = '{"code": "M10.PackLoading", "version": 1, "initialState": "DRAFT", "states": [{"code": "DRAFT"}, {"code": "GATE_PASS_CREATED", "assignedRole": "ParkingSecurity"}, {"code": "PARKING_IN_1", "assignedRole": "Dispatch"}, {"code": "DISPATCH_VEHICLE_ENTRY", "assignedRole": "QC"}, {"code": "QC_PRELOAD_APPROVED", "assignedRole": "Planning"}, {"code": "QC_PRELOAD_REJECTED", "terminal": true}, {"code": "LOADING_ALLOCATED", "assignedRole": "WeighmentOfficer"}, {"code": "PARKING_OUT_1", "assignedRole": "WeighmentOfficer"}, {"code": "WEIGHMENT_1", "assignedRole": "LoadingSupervisor"}, {"code": "LOADING_IN_PROGRESS", "assignedRole": "WeighmentOfficer"}, {"code": "WEIGHMENT_2", "assignedRole": "LoadingSupervisor"}, {"code": "SEALING_DONE", "assignedRole": "ParkingSecurity"}, {"code": "PARKING_IN_2", "assignedRole": "PMTTeam"}, {"code": "PMT_CHECK_OK", "assignedRole": "BillingOfficer"}, {"code": "PMT_CAMERA_VERIFICATION", "assignedRole": "PMTTeam"}, {"code": "PMT_CHECK_PENDING_MANAGER", "assignedRole": "Manager"}, {"code": "RELOAD_REQUIRED", "assignedRole": "LoadingSupervisor"}, {"code": "BILLING_DONE", "assignedRole": "WeighmentOfficer"}, {"code": "PARKING_OUT_2", "assignedRole": "WeighmentOfficer"}, {"code": "WEIGHMENT_3", "assignedRole": "Manager"}, {"code": "READY_FOR_EXIT", "assignedRole": "FrontGate"}, {"code": "GATE_PASS_OUT_CLOSED", "terminal": true}, {"code": "REJECTED_BY_MANAGER", "terminal": true}, {"code": "UNLOAD_REQUIRED", "role": "UnloadingSupervisor"}], "transitions": [{"from": "DRAFT", "to": "GATE_PASS_CREATED", "trigger": "page.submitted", "pageCode": "aria:front-gate-create"}, {"from": "GATE_PASS_CREATED", "to": "PARKING_IN_1", "trigger": "page.submitted", "pageCode": "aria:parking-scan"}, {"from": "PARKING_IN_1", "to": "DISPATCH_VEHICLE_ENTRY", "trigger": "page.submitted", "pageCode": "aria:dispatch-vehicle-details"}, {"from": "DISPATCH_VEHICLE_ENTRY", "to": "QC_PRELOAD_APPROVED", "trigger": "page.submitted", "pageCode": "aria:qc-preload-approval", "guard": "#submitted[''status''] == ''APPROVED''"}, {"from": "DISPATCH_VEHICLE_ENTRY", "to": "QC_PRELOAD_REJECTED", "trigger": "page.submitted", "pageCode": "aria:qc-preload-approval", "guard": "#submitted[''status''] == ''REJECTED''"}, {"from": "QC_PRELOAD_APPROVED", "to": "LOADING_ALLOCATED", "trigger": "page.submitted", "pageCode": "aria:loading-allocation"}, {"from": "LOADING_ALLOCATED", "to": "PARKING_OUT_1", "trigger": "page.submitted", "pageCode": "aria:parking-scan"}, {"from": "PARKING_OUT_1", "to": "WEIGHMENT_1", "trigger": "page.submitted", "pageCode": "aria:weighment-capture"}, {"from": "WEIGHMENT_1", "to": "LOADING_IN_PROGRESS", "trigger": "page.submitted", "pageCode": "aria:loading-in-progress"}, {"from": "LOADING_IN_PROGRESS", "to": "WEIGHMENT_2", "trigger": "page.submitted", "pageCode": "aria:weighment-capture"}, {"from": "WEIGHMENT_2", "to": "SEALING_DONE", "trigger": "page.submitted", "pageCode": "aria:sealing-process"}, {"from": "SEALING_DONE", "to": "PARKING_IN_2", "trigger": "page.submitted", "pageCode": "aria:parking-scan"}, {"from": "PARKING_IN_2", "to": "PMT_CHECK_OK", "trigger": "page.submitted", "pageCode": "aria:pmt-weight-diff-check", "guard": "#submitted[''withinTolerance''] == ''YES''"}, {"from": "PARKING_IN_2", "to": "PMT_CAMERA_VERIFICATION", "trigger": "page.submitted", "pageCode": "aria:pmt-weight-diff-check", "guard": "#submitted[''withinTolerance''] == ''NO''"}, {"from": "PMT_CAMERA_VERIFICATION", "to": "PMT_CHECK_PENDING_MANAGER", "trigger": "page.submitted", "pageCode": "aria:pmt-camera-verification"}, {"from": "PMT_CHECK_PENDING_MANAGER", "to": "PMT_CHECK_OK", "trigger": "page.submitted", "pageCode": "aria:manager-qty-approval", "guard": "#submitted[''status''] == ''APPROVED''"}, {"from": "PMT_CHECK_PENDING_MANAGER", "to": "UNLOAD_REQUIRED", "trigger": "page.submitted", "pageCode": "aria:manager-qty-approval", "guard": "#submitted[''status''] == ''REJECTED''"}, {"from": "RELOAD_REQUIRED", "to": "WEIGHMENT_2", "trigger": "page.submitted", "pageCode": "aria:weighment-capture"}, {"from": "PMT_CHECK_OK", "to": "BILLING_DONE", "trigger": "page.submitted", "pageCode": "aria:billing-entry"}, {"from": "BILLING_DONE", "to": "PARKING_OUT_2", "trigger": "page.submitted", "pageCode": "aria:parking-scan"}, {"from": "PARKING_OUT_2", "to": "WEIGHMENT_3", "trigger": "page.submitted", "pageCode": "aria:weighment-capture"}, {"from": "WEIGHMENT_3", "to": "READY_FOR_EXIT", "trigger": "page.submitted", "pageCode": "aria:manager-weight-approval", "guard": "#submitted[''status''] == ''APPROVED''"}, {"from": "WEIGHMENT_3", "to": "REJECTED_BY_MANAGER", "trigger": "page.submitted", "pageCode": "aria:manager-weight-approval", "guard": "#submitted[''status''] == ''REJECTED''"}, {"from": "READY_FOR_EXIT", "to": "GATE_PASS_OUT_CLOSED", "trigger": "page.submitted", "pageCode": "aria:gate-pass-closure-form", "guard": "(#submitted[''weighment_verified''] == ''OK'' || #submitted[''weighment_verified''] == ''MGR_APPROVED'') && (#submitted[''seal_verified''] == ''MATCHED'' || #submitted[''seal_verified''] == ''NA'') && #submitted[''invoice_count_verified''] == ''YES''"}, {"from": "UNLOAD_REQUIRED", "to": "RELOAD_REQUIRED", "pageCode": "aria:pmt-unload-recheck", "trigger": "page.submitted"}]}'
 WHERE code = 'M10.PackLoading';

-- 2) delete the weak duplicate order page (FK-safe: versions first)
DELETE pv FROM page_version pv
  JOIN page_definition pd ON pv.page_id = pd.id
 WHERE pd.code = 'aria:loading-order-sheet';
DELETE FROM page_definition WHERE code = 'aria:loading-order-sheet';

-- 3) re-point unload-recheck at its OWN published version (fix V37 bad pointer)
UPDATE page_definition pd
   SET pd.current_version_id = (
        SELECT pv.id FROM page_version pv
         WHERE pv.page_id = pd.id AND pv.status = 'PUBLISHED'
         ORDER BY pv.id DESC LIMIT 1)
 WHERE pd.code = 'aria:pmt-unload-recheck'
   AND EXISTS (SELECT 1 FROM page_version pv2
                WHERE pv2.page_id = pd.id AND pv2.status = 'PUBLISHED');
